# %% [markdown]
# # CASMI 2026 — specs_scratch R2: NPClassifier labels for the pool (Colab)
#
# **Generated by `scratch_pkg/tools/mk_notebook.py r2_npc_colab` from `scratch_pkg/drivers/r2_npc_colab.py` —
# do not hand-edit.** Gates R2.0 / R2.1 pre-registered in `specs/specs_scratch/gate_report.md` (R2 section).
# Needs `casmi_2026/casmi26-scratch-pool/` (v1, from `casmi_scratch_r1_pool_colab.ipynb`).
#
# Runtime: **T4 GPU** (CPU works, slower), **internet ON** (NPClassifier weights from Zenodo 5068687, label index from
# github.com/mwang87/NP-Classifier, MIT). Downloads are cached in `casmi_2026/_npc/`. Labels are checkpointed per
# chunk in `casmi_2026/_npc/ckpt_fp2021/`: after a disconnect, **re-run all cells** and it resumes.
#
# Why a side env: NP-Classifier V1 was trained on RDKit <= 2021.03 Morgan bits, and RDKit 2021.09 changed them (R2.0
# FAIL, 1/50). Fingerprints come from `uv run --python 3.9 --with rdkit-pypi==2021.3.5`; TensorFlow and RDKit
# 2026.03.3 stay in this notebook's interpreter.
#
# | stage | what |
# |---|---|
# | R2.0b spike | weights load; fingerprints from RDKit 2021.03.5 (side env, `npc_fp_worker.py`); parity with the repo's `calculate_fingerprint` on 50 table-labelled rows; top-1 superclass ∈ table label for ≥ 45/50; 14 known structures shown; 10k SMILES timed |
# | R2.1 labels | all pool rows → top-3 superclass + pathway + class → `pool_npc.parquet`, MANIFEST → version v2 |
#
# After it finishes: upload `casmi_2026/casmi26-scratch-pool/` as a **new version** of the Kaggle dataset
# `casmi26-scratch-pool`. Paste the final printout back into the chat.

# %%
LABELLER = "npc"           # "lr" = the pre-registered fallback if R2.0 fails (logistic regression on table labels)

# %%
import json, os, subprocess, sys, time
from pathlib import Path

from google.colab import drive
drive.mount("/content/drive")

ROOT = Path(os.environ.get("CASMI_INPUT", "/content/drive/MyDrive/casmi_2026"))
POOL_DIR = ROOT / "casmi26-scratch-pool"
NPC_DIR = ROOT / "_npc"
WORKERS = os.cpu_count() or 2
PKG_FILES = None  # @@PKG_FILES@@
PKG_ROOT = Path("/content/pkg")
for rel, src in PKG_FILES.items():
    p = PKG_ROOT / rel
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(src, encoding="utf-8")
sys.path.insert(0, str(PKG_ROOT))
NPC_DIR.mkdir(parents=True, exist_ok=True)

RDKIT_PIN = "2026.03.3"
r_ = subprocess.run([sys.executable, "-m", "pip", "install", "-q", f"rdkit=={RDKIT_PIN}", "tf_keras", "uv"],
                    capture_output=True, text=True)
if r_.returncode != 0:
    raise RuntimeError("pip failed:\n" + r_.stdout[-2000:] + "\n" + r_.stderr[-2000:])
import rdkit  # noqa: E402
assert rdkit.__version__ == RDKIT_PIN, rdkit.__version__

import numpy as np  # noqa: E402
import pandas as pd  # noqa: E402
import pyarrow.parquet as pq  # noqa: E402

from casmi_scratch import npc  # noqa: E402
from casmi_scratch.analog import label_match  # noqa: E402
from casmi_scratch.pool_build import _sha1  # noqa: E402

FP = npc.fp_fn_subprocess(workers=WORKERS)   # fingerprints under rdkit-pypi 2021.3.5 (side env)
T0 = time.time()

# %%
# downloads (cached on Drive)
ZIP = NPC_DIR / "model.zip"
REPO = "https://raw.githubusercontent.com/mwang87/NP-Classifier/master/Classifier"
for url, dst in ((f"https://zenodo.org/record/5068687/files/model.zip?download=1", ZIP),
                 (f"{REPO}/dict/index_v1.json", NPC_DIR / "index_v1.json"),
                 (f"{REPO}/fingerprint_handler.py", NPC_DIR / "fingerprint_handler.py")):
    if not dst.exists():
        subprocess.run(["wget", "-q", "-O", str(dst), url], check=True)
if not list(NPC_DIR.glob("**/NP_classifier_superclass_V1.hdf5")):
    subprocess.run(["unzip", "-o", "-q", str(ZIP), "-d", str(NPC_DIR / "models")], check=True)
MODEL_DIR = next(NPC_DIR.glob("**/NP_classifier_superclass_V1.hdf5")).parent
NAMES = npc.label_names(NPC_DIR / "index_v1.json")
print({h: len(v) for h, v in NAMES.items()}, "| models in", MODEL_DIR)

keys = np.load(POOL_DIR / "pool_key.npy").astype(str)
smiles = pq.read_table(POOL_DIR / "pool_smiles.parquet").column("smiles").to_numpy(zero_copy_only=False).astype(object)
side = pq.read_table(POOL_DIR / "pool_np.parquet", columns=["key", "np_superclass", "label_source"]).to_pandas()
assert np.array_equal(side.key.to_numpy().astype(str), keys)
MANIFEST = json.loads((POOL_DIR / "MANIFEST.json").read_text())
print(f"pool {MANIFEST['version']}: {len(keys):,} structures")
table = np.flatnonzero((side.label_source.to_numpy() == 1) & side.np_superclass.notna().to_numpy())

# %% [markdown]
# ## R2.0b spike (fingerprints from RDKit 2021.03.5)

# %%
SPIKE = NPC_DIR / f"spike_{LABELLER}_r20b.json"          # R2.0b; spike_npc.json holds the failed R2.0
SANITY = dict(quercetin=("O=C1C(O)=C(Oc2cc(O)cc(O)c12)c1ccc(O)c(O)c1", "Flavonoids"),
              naringenin=("O=C1CC(c2ccc(O)cc2)Oc2cc(O)cc(O)c21", "Flavonoids"),
              cholesterol=("CC(C)CCCC(C)C1CCC2C1(CCC3C2CC=C4C3(CCC(C4)O)C)C", "Steroids"),
              testosterone=("CC12CCC3C(CCC4=CC(=O)CCC34C)C1CCC2O", "Steroids"),
              palmitic=("CCCCCCCCCCCCCCCC(=O)O", "Fatty Acids and Conjugates"),
              oleic=("CCCCCCCCC=CCCCCCCCC(=O)O", "Fatty Acids and Conjugates"),
              caffeine=("Cn1cnc2c1c(=O)n(C)c(=O)n2C", "Pseudoalkaloids"),
              nicotine=("CN1CCCC1c1cccnc1", "Nicotinic acid alkaloids"),
              limonene=("CC1=CCC(CC1)C(=C)C", "Monoterpenoids"),
              menthol=("CC(C)C1CCC(C)CC1O", "Monoterpenoids"),
              glucose=("OCC1OC(O)C(O)C(O)C1O", "Saccharides"),
              strychnine=("O=C1CC2OCC=C3CN4CCC56C4CC3C2C6N1c1ccccc15", "Tryptophan alkaloids"),
              emodin=("Cc1cc(O)c2c(c1)C(=O)c1cc(O)cc(O)c1C2=O", "Polycyclic aromatic polyketides"),
              artemisinin=("CC1CCC2C(C)C(=O)OC3OC4(C)CCC1C32OO4", "Sesquiterpenoids"))
if LABELLER == "npc":
    MODELS = npc.load_models(str(MODEL_DIR))
    for h, m in MODELS.items():
        print(h, [tuple(t.shape) for t in m.inputs], "->", tuple(m.outputs[0].shape))
        assert m.outputs[0].shape[-1] == len(NAMES[h]), (h, m.outputs[0].shape, len(NAMES[h]))
    if SPIKE.exists():
        spike = json.loads(SPIKE.read_text())
    else:
        rng = np.random.default_rng(0)
        pick = rng.choice(table, 50, replace=False)
        t = time.time()
        F, B, ok, meta = npc.fp_subprocess(smiles[pick], workers=WORKERS, ref_dir=NPC_DIR)   # parity in the old env
        print(f"fingerprint env: RDKit {meta['rdkit']} | first call (env build) {time.time() - t:.0f}s")
        lab = npc.predict(smiles[pick], MODELS, NAMES, lambda _s: (F, B, ok))
        hit = [label_match(p, t) for p, t in zip(lab.sc1, side.np_superclass.to_numpy()[pick])]
        san = npc.predict([v[0] for v in SANITY.values()], MODELS, NAMES, FP)
        sanity = {k: dict(expected=v[1], got=str(g), p=round(float(p), 3), ok=g == v[1])
                  for (k, v), g, p in zip(SANITY.items(), san.sc1, san.sp1)}
        t = time.time()
        npc.predict(smiles[rng.choice(len(smiles), 10_000, replace=False)], MODELS, NAMES, FP)
        spike = dict(fp_rdkit=meta["rdkit"], parity=int(meta["parity"]), top1_in_table=int(sum(hit)), n=50,
                     s_per_10k=round(time.time() - t, 1), sanity_ok=int(sum(v["ok"] for v in sanity.values())),
                     sanity=sanity,
                     misses=[(str(p), str(t)) for p, t, h in zip(lab.sc1, side.np_superclass.to_numpy()[pick], hit)
                             if not h][:10])
        spike["pass"] = bool(spike["parity"] == 50 and spike["top1_in_table"] >= 45)
        SPIKE.write_text(json.dumps(spike, indent=1))
    print(json.dumps(spike, indent=1))
    print(f"est. full pool: {spike['s_per_10k'] * len(smiles) / 1e4 / 60:.0f} min")
    if not spike["pass"]:
        raise SystemExit("R2.0b FAIL: paste this printout; the fallback is LABELLER = 'lr' (pre-registered)")
else:
    from sklearn.model_selection import train_test_split
    first = side.np_superclass.to_numpy()[table]
    first = np.array([str(v).replace(";", "|").split("|")[0].strip() for v in first], dtype=object)
    tr, te = train_test_split(np.arange(len(table)), test_size=0.1, random_state=0)
    CLF = npc.lr_fit(smiles[table[tr]], first[tr])
    acc = float(np.mean(npc.lr_predict(CLF, smiles[table[te]]).sc1.to_numpy() == first[te]))
    spike = dict(labeller="lr", holdout_acc=acc, n_train=len(tr), n_holdout=len(te))
    SPIKE.write_text(json.dumps(spike, indent=1))
    print(json.dumps(spike, indent=1))

# %% [markdown]
# ## R2.1 label every pool structure

# %%
t = time.time()
if LABELLER == "npc":
    LAB = npc.label_all(smiles, MODELS, NAMES, str(NPC_DIR / "ckpt_fp2021"), fp_fn=FP)
else:
    LAB = pd.concat([npc.lr_predict(CLF, list(smiles[i:i + 50_000])) for i in range(0, len(smiles), 50_000)],
                    ignore_index=True)
ok = LAB.sc1.notna().to_numpy()
agree = [label_match(p, tl) for p, tl in zip(LAB.sc1.to_numpy()[table], side.np_superclass.to_numpy()[table])]
r21 = dict(labeller=LABELLER, n=len(LAB), labelled=int(ok.sum()), unparsable=int((~ok).sum()),
           table_rows=len(table), top1_agree_table=float(np.mean(agree)),
           sc1_top=LAB.sc1.value_counts().head(10).to_dict(), sp1_median=float(np.nanmedian(LAB.sp1)),
           minutes=round((time.time() - t) / 60, 1))
print(json.dumps(r21, indent=1))

# %%
npc.write_npc(str(POOL_DIR), LAB)
MANIFEST.update(version="v2", npc=dict(r21, spike=spike, source="mwang87/NP-Classifier (MIT), Zenodo 5068687",
                                       built=time.strftime("%Y-%m-%d %H:%M"), rdkit=rdkit.__version__,
                                       fp_rdkit=spike.get("fp_rdkit")))
MANIFEST.setdefault("files", {})[npc.NPC_FILE] = dict(bytes=os.path.getsize(POOL_DIR / npc.NPC_FILE),
                                                      sha1=_sha1(POOL_DIR / npc.NPC_FILE))
(POOL_DIR / "MANIFEST.json").write_text(json.dumps(MANIFEST, indent=1, default=str))
print(f"R2.1 {'PASS' if r21['labelled'] + r21['unparsable'] == len(keys) and r21['labelled'] > 0 else 'FAIL'}: "
      f"{r21['labelled']:,} labelled, {r21['unparsable']:,} unparsable, top-1 agreement with table "
      f"{r21['top1_agree_table']:.3f} | wrote {npc.NPC_FILE}, MANIFEST v2 | {(time.time() - T0) / 60:.0f} min")
